USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkflowRule_Evaluate @AssetId BIGINT,@ReqType VARCHAR(20),@Amount DECIMAL(18,2),@AsOfDate DATE=NULL
AS BEGIN SET NOCOUNT ON; SET @AsOfDate=COALESCE(@AsOfDate,CONVERT(DATE,SYSUTCDATETIME())); SELECT TOP(1) WORKFLOW_RULE_ID,RULE_CODE,RULE_NAME,CONCERN_DIVISION_ID,AUTHORITY_BEFORE_DIVISION,DESTINATION_AFTER_CONCERN,PRIORITY_ORDER FROM dbo.WORKFLOW_RULE WHERE ASSET_ID=@AssetId AND REQ_TYPE=@ReqType AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=@AsOfDate AND (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=@AsOfDate) AND (MIN_AMOUNT IS NULL OR @Amount>=MIN_AMOUNT) AND (MAX_AMOUNT IS NULL OR @Amount<=MAX_AMOUNT) ORDER BY PRIORITY_ORDER,CASE WHEN MIN_AMOUNT IS NULL THEN 1 ELSE 0 END,COALESCE(MAX_AMOUNT,9999999999999999)-COALESCE(MIN_AMOUNT,0),WORKFLOW_RULE_ID; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkflowRule_GetByAsset @AssetId BIGINT,@ActiveOnly BIT=1 AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.WORKFLOW_RULE WHERE ASSET_ID=@AssetId AND (@ActiveOnly=0 OR IS_ACTIVE=1) ORDER BY REQ_TYPE,PRIORITY_ORDER,MIN_AMOUNT; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkflowRule_Save @WorkflowRuleId BIGINT=NULL,@RuleCode VARCHAR(40),@RuleName NVARCHAR(200),@AssetId BIGINT,@ReqType VARCHAR(20),@MinAmount DECIMAL(18,2)=NULL,@MaxAmount DECIMAL(18,2)=NULL,@ConcernDivisionId BIGINT=NULL,@AuthorityBeforeDivision BIT=0,@DestinationAfterConcern VARCHAR(30),@PriorityOrder INT=100,@IsActive BIT=1,@EffectiveFrom DATE,@EffectiveTo DATE=NULL,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY BEGIN TRAN; IF EXISTS(SELECT 1 FROM dbo.WORKFLOW_RULE WITH(UPDLOCK,HOLDLOCK) WHERE WORKFLOW_RULE_ID<>COALESCE(@WorkflowRuleId,-1) AND ASSET_ID=@AssetId AND REQ_TYPE=@ReqType AND PRIORITY_ORDER=@PriorityOrder AND IS_ACTIVE=1 AND @IsActive=1 AND EFFECTIVE_FROM<=COALESCE(@EffectiveTo,'99991231') AND COALESCE(EFFECTIVE_TO,'99991231')>=@EffectiveFrom AND COALESCE(MIN_AMOUNT,0)<=COALESCE(@MaxAmount,9999999999999999.99) AND COALESCE(MAX_AMOUNT,9999999999999999.99)>=COALESCE(@MinAmount,0)) THROW 51000,'Conflicting active workflow rule range and priority.',1; IF @WorkflowRuleId IS NULL BEGIN INSERT dbo.WORKFLOW_RULE(RULE_CODE,RULE_NAME,ASSET_ID,REQ_TYPE,MIN_AMOUNT,MAX_AMOUNT,CONCERN_DIVISION_ID,AUTHORITY_BEFORE_DIVISION,DESTINATION_AFTER_CONCERN,PRIORITY_ORDER,IS_ACTIVE,EFFECTIVE_FROM,EFFECTIVE_TO,CREATED_BY) VALUES(@RuleCode,@RuleName,@AssetId,@ReqType,@MinAmount,@MaxAmount,@ConcernDivisionId,@AuthorityBeforeDivision,@DestinationAfterConcern,@PriorityOrder,@IsActive,@EffectiveFrom,@EffectiveTo,@Actor); SET @WorkflowRuleId=SCOPE_IDENTITY(); END ELSE UPDATE dbo.WORKFLOW_RULE SET RULE_NAME=@RuleName,ASSET_ID=@AssetId,REQ_TYPE=@ReqType,MIN_AMOUNT=@MinAmount,MAX_AMOUNT=@MaxAmount,CONCERN_DIVISION_ID=@ConcernDivisionId,AUTHORITY_BEFORE_DIVISION=@AuthorityBeforeDivision,DESTINATION_AFTER_CONCERN=@DestinationAfterConcern,PRIORITY_ORDER=@PriorityOrder,IS_ACTIVE=@IsActive,EFFECTIVE_FROM=@EffectiveFrom,EFFECTIVE_TO=@EffectiveTo,MODIFIED_BY=@Actor,MODIFIED_DATE=SYSUTCDATETIME() WHERE WORKFLOW_RULE_ID=@WorkflowRuleId; COMMIT; SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,@WorkflowRuleId ENTITY_ID,@RuleCode REFERENCE_NO; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SELECT CASE WHEN ERROR_NUMBER()=51000 THEN '005' WHEN ERROR_NUMBER() IN(2601,2627) THEN '005' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,@WorkflowRuleId ENTITY_ID,@RuleCode REFERENCE_NO; END CATCH END;
GO
